// The antialiased saturators and wavefolders of aanl.lib as modules, generated by
// build-faust-library-modules.mjs as the filters (faust-filter-modules.mjs).
//
// - Drive in dB, before the curve; Bias: an offset before it (asymmetry, even harmonics), the value of the
//   curve at Bias removed after it (a high pass would overshoot on the flat tops of a clipped sound); Mix: from the dry sound (0) to the shaped one (1); Level in dB, after.
// - Antialiasing: the curves of aanl.lib are computed by the antiderivative method (ADAA), of the first or of
//   the second order: the harmonics above Nyquist fold back much less than through the curve itself. Measured
//   on a hard clip of a sine at 4987 Hz driven by 24 dB, the aliases fall from -11.1 dB of the power through the
//   curve to -18.1 dB (first order) and -22.3 dB (second order).
// - No smoothing.
//
// Family: Lib saturation (in FAUST_LIBRARY_FAMILIES), with the Cubic Distortion and the Transformer of demos.lib.

const DRIVE = (index, deflt, max) => `drive = hslider("[${index}]Drive[unit:dB]", ${deflt}, 0, ${max}, 0.1) : ba.db2linear;`;
const COMMON = (first) => `bias = hslider("[${first}]Bias", 0, -1, 1, 0.01);
mix = hslider("[${first + 1}]Mix", 1, 0, 1, 0.01);
level = hslider("[${first + 2}]Level[unit:dB]", 0, -24, 12, 0.1) : ba.db2linear;
// from the dry sound to the shaped one
// the offset of the curve at Bias removed: f(x + Bias) - f(Bias) (a high pass would overshoot on the flat tops)
wet(curve) = _ <: _, (*(drive) : +(bias) : curve : -(bias : curve)) : \\(dry, shaped).(dry + mix * (shaped - dry)) : *(level);`;
const ORDER = (index) => `order = hslider("[${index}]Antialiasing[style:menu{'first order':0;'second order':1}]", 0, 0, 1, 1);`;

export const SATURATION_MODULES = [
    {
        family: "Lib saturation", name: "Waveshaper", file: "Waveshaper", source: "aa.hardclip, aa.cubic1, aa.tanh1, aa.arctan, aa.sinarctan, aa.hyperbolic, aa.parabolic, aa.softclipQuadratic1, aa.asinh1 and their second orders (aanl.lib)", inlets: "audio", outlets: "audio",
        summary: [
            "Waveshaper, antialiased: the sound through a saturation curve computed by the antiderivative method (ADAA), of the first or of the second order",
            "Shape: hard clip, cubic, tanh, arctan, sin(arctan), hyperbolic, parabolic, quadratic, asinh; each kept within [-1, 1] (cubic by 1.5, arctan by 2/pi), but asinh, which grows as a logarithm",
            "Drive (dB): the gain before the curve; Bias: an offset before it, for even harmonics (the value of the curve at Bias removed after); Mix: from the dry sound to the shaped one; Level (dB)",
            "Their slope at 0: 1, but 1.5 for cubic, 2/pi for arctan and 2 for quadratic; the second order is used where aanl.lib has one (not for cubic and tanh, which keep the first)",
            "Drive up to 36 dB: beyond, the antiderivative of tanh, log(cosh(x)), overflows in single precision (|x| > 89); in single precision the second order overshoots at low frequencies when driven hard (measured at 50 Hz: 1% at 24 dB, up to 6% at 30 dB and 44% at 36 dB, for arctan): the first order stays within [-1, 1]",
        ],
        body: `process = wet(shaped);

shape = hslider("[0]Shape[style:menu{'hard clip':0;'cubic':1;'tanh':2;'arctan':3;'sin arctan':4;'hyperbolic':5;'parabolic':6;'quadratic':7;'asinh':8}]", 2, 0, 8, 1);
${ORDER(1)}
${DRIVE(2, 12, 36)}
${COMMON(3)}

// the curves, kept within [-1, 1] (cubic: 2/3, arctan: pi/2), first then second order
shaped = _ <: aa.hardclip, (aa.cubic1 : *(1.5)), aa.tanh1, (aa.arctan : *(2 / ma.PI)), aa.sinarctan, aa.hyperbolic,
    aa.parabolic, aa.softclipQuadratic1, aa.asinh1,
    aa.hardclip2, (aa.cubic1 : *(1.5)), aa.tanh1, (aa.arctan2 : *(2 / ma.PI)), aa.sinarctan2, aa.hyperbolic2,
    aa.parabolic2, aa.softclipQuadratic2, aa.asinh2 : ba.selectn(18, 9 * order + shape);`,
    },
    {
        family: "Lib saturation", name: "Wavefolder", file: "Wavefolder", source: "aa.triangleFold1, aa.sineFold1, aa.triangleFold2, aa.sineFold2 (aanl.lib)", inlets: "audio", outlets: "audio",
        summary: [
            "Wavefolder, antialiased: the sound passes unchanged within [-1, 1], and beyond is folded back, as many times as needed",
            "Shape: triangle (folded linearly) or sine (each fold a half cosine, smoother); Antialiasing: first or second order (ADAA)",
            "Drive (dB): the gain before the folder, how many folds; Damping: each fold smaller than the previous one (0: periodic folding)",
            "Bias: an offset before the folder (its value at Bias removed after); Mix: from the dry sound to the folded one; Level (dB)",
        ],
        body: `process = wet(folded);

shape = hslider("[0]Shape[style:menu{'triangle':0;'sine':1}]", 0, 0, 1, 1);
${ORDER(1)}
${DRIVE(2, 12, 36)}
damping = hslider("[3]Damping", 0, 0, 0.9, 0.01);
${COMMON(4)}

folded = _ <: aa.triangleFold1(1, r), aa.sineFold1(1, r), aa.triangleFold2(1, r), aa.sineFold2(1, r) : ba.selectn(4, 2 * order + shape)
with {
    r = 1 - damping;
};`,
    },
];
